console.log("Archivo min.js cargado");


(function($){
    var prefix = 'automatorwp-constant-contact-';
    var _prefix = 'automatorwp_constant_contact_';

    // Manejo del clic para autorizar con Constant Contact
    $('body').on('click', '.automatorwp_settings #' + _prefix + 'authorize', function(e) {
        console.log("b");
        e.preventDefault();
        var button = $(this);
        var wrapper = button.parent();
        var client_id = $('#' + _prefix + 'client_id').val();
        var client_secret = $('#' + _prefix + 'client_secret').val();
        var response_wrap = wrapper.find('#' + _prefix + 'response');

        console.log(client_id, client_secret);

        // Verificar si los campos están completos
        if (!response_wrap.length) {
            wrapper.append('<div id="' + _prefix + 'response" style="display: none; margin-top: 10px;"></div>');
            response_wrap = wrapper.find('#' + _prefix + 'response');
        }

        if (client_id.length === 0 || client_secret.length === 0) {
            response_wrap.addClass('automatorwp-notice-error');
            response_wrap.html('All fields are required to connect with Constant Contact');
            response_wrap.slideDown('fast');
            return;
        }

        response_wrap.slideUp('fast');
        response_wrap.attr('class', '');
        wrapper.append('<span class="spinner is-active" style="float: none;"></span>');
        button.prop('disabled', true);


        // Realizar el POST con los datos para autorización
        $.post(ajaxurl, {
            action: 'automatorwp_constant_contact_authorize',
            nonce: automatorwp_constant_contact.nonce,  // Asegúrate de que este valor esté bien configurado
            client_id: client_id,
            client_secret: client_secret
        }, function(response) {

            console.log(response);
            if (!response || !response.success) {
                // Maneja el caso en que la respuesta no tiene éxito o no es válida
                response_wrap.addClass('automatorwp-notice-error');
                response_wrap.html('An error occurred. Please try again.');
                response_wrap.slideDown('fast');
                wrapper.find('.spinner').remove();
                button.prop('disabled', false);
                console.error('Invalid response:', response);
                return;
            }
        
            // Asegúrate de que `response.data` es un objeto antes de acceder a él
            var responseData = response.data || {};
            response_wrap.addClass('automatorwp-notice-' + (response.success ? 'success' : 'error'));
            response_wrap.html(responseData.message !== undefined ? responseData.message : responseData);
            response_wrap.slideDown('fast');
            wrapper.find('.spinner').remove();
        
            console.log(response); 
        
            if (response.success && responseData.access_token) {
                var result_html = '<p>Access Token: ' + responseData.access_token + '</p>';
                result_html += '<p>Refresh Token: ' + responseData.refresh_token + '</p>';
                $('#access-token-result').html(result_html).show();
            }
        
            if (response.success && responseData.url !== undefined) {
                window.location.href = responseData.url;
                return;
            }
        
            button.prop('disabled', false);
        }).fail(function() {
            response_wrap.addClass('automatorwp-notice-error');
            response_wrap.html('An error occurred. Please try again.');
            response_wrap.slideDown('fast');
            wrapper.find('.spinner').remove();
            button.prop('disabled', false);
        });
        
        
    });

    // Manejo de cambio en el selector de listas de contactos de Constant Contact
    $('body').on('change', '.automatorwp-action-constant-contact-add-contact .cmb2-id-list select, ' +
        '.automatorwp-trigger-automatorwp-import-file .cmb2-id-csv-list select', function(e) {
        var row = $(this).closest('.cmb-row');
        var list_row = row.next('.cmb2-id-contact-list');
        var list_id = $(this).val();
        var first_change = row.hasClass('is-option-change');

        if (list_id === 'any' || list_id === '') {
            if (first_change) {
                list_row.hide();
            } else {
                list_row.slideUp('fast');
            }
        } else {
            var contact_selector = list_row.find('select.select2-hidden-accessible');
            contact_selector.next('.select2').remove();
            contact_selector.data('list', list_id);
            contact_selector.removeAttr('data-select2-id');
            automatorwp_ajax_selector(contact_selector);

            if (first_change) {
                list_row.show();
            } else {
                list_row.slideDown('fast');
            }
        }

        row.removeClass('is-option-change');
    });

    // Manejo del clic en un ítem de automatización para cambiar la opción de la lista de contactos
    $('body').on('click', '.automatorwp-automation-item-label > .automatorwp-option', function(e) {
        var item = $(this).closest('.automatorwp-automation-item');
        var option = $(this).data('option');
        var option_form = item.find('.automatorwp-option-form-container[data-option="' + option + '"]');
        var list_selector = option_form.find('.cmb2-id-list');

        if (list_selector !== undefined) {
            list_selector.addClass('is-option-change');
            list_selector.find('select.select2-hidden-accessible').trigger('change');
        }
    });

})(jQuery);